58	    throw bomResult.error;
59	  }
60	
61	  const boms = Array.isArray(bomResult.data) ? bomResult.data : [];
62	  const bomIds = boms.map((row) => row?.id).filter(Boolean);
63	  if (!bomIds.length) return new Map();
64	
65	  const versionsResult = await supabaseAdmin
66	    .from("production_bom_versions")
67	    .select("id,bom_id,version_no,formula_code,formula_name,status")
