75	  const skuByBomId = new Map(boms.map((row) => [row.id, normalizeSku(row.sku_code)]));
76	  const optionsBySku = new Map();
77	  (versionsResult.data ?? []).forEach((version) => {
78	    const sku = skuByBomId.get(version?.bom_id);
79	    if (!sku) return;
80	    if (!optionsBySku.has(sku)) {
81	      optionsBySku.set(sku, new Map());
