89	      bom_version_id: version?.id || null,
90	    });
91	  });
92	
93	  return new Map(
94	    Array.from(optionsBySku.entries()).map(([sku, formulaMap]) => [sku, Array.from(formulaMap.values())])
95	  );
96	}
