94	      const assignOwnerResult = await supabaseAdmin
95	        .from("production_department_products")
96	        .update({ is_owner: true })
97	        .eq("department_id", departmentId)
98	        .in("sku_code", ownerSkuCodes);
99	      if (assignOwnerResult.error) {
100	        return Response.json({ error: "Failed to assign product owner" }, { status: 500 });
101	      }
102	    } else {
