106	        .in("sku_code", skuCodes)
107	        .eq("is_owner", true);
108	      if (existingOwnerResult.error) {
109	        return Response.json({ error: "Failed to validate product owners" }, { status: 500 });
110	      }
111	
112	      const ownerSkuSet = new Set(
113	        (existingOwnerResult.data ?? [])
114	          .map((row) => String(row?.sku_code || "").trim().toUpperCase())
115	          .filter(Boolean)
116	      );
117	      const missingOwnerSkus = skuCodes.filter((skuCode) => !ownerSkuSet.has(skuCode));
