137	export async function DELETE(request) {
138	  try {
139	    await requirePermissionKeys(request, [
140	      "production-line-settings-manage",
141	    ]);
142	
143	    const body = await readJson(request);
144	    const departmentId = normalizeParam(body.departmentId);
145	    const skuCodes = normalizeSkuCodes(body.skuCodes);
146	
147	    if (!departmentId || !skuCodes.length) {
148	      return Response.json({ error: "departmentId and skuCodes are required" }, { status: 400 });
149	    }
150	
151	    const supabaseAdmin = getSupabaseAdmin();
152	    const ownerRowsResult = await supabaseAdmin
153	      .from("production_department_products")
154	      .select("sku_code,is_owner")
155	      .eq("department_id", departmentId)
156	      .in("sku_code", skuCodes);
157	    if (ownerRowsResult.error) {
158	      return Response.json({ error: "Failed to load product ownership before delete" }, { status: 500 });
159	    }
160	    const removedOwnerSkus = Array.from(
161	      new Set(
162	        (ownerRowsResult.data ?? [])
163	          .filter((row) => Boolean(row?.is_owner))
164	          .map((row) => String(row?.sku_code || "").trim().toUpperCase())
165	          .filter(Boolean)
166	      )
167	    );
168	
169	    const { error } = await supabaseAdmin
170	      .from("production_department_products")
171	      .delete()
172	      .eq("department_id", departmentId)
173	      .in("sku_code", skuCodes);
174	
175	    if (error) {
176	      return Response.json({ error: "Failed to remove products from department" }, { status: 500 });
177	    }
178	
179	    if (removedOwnerSkus.length) {
180	      const fallbackRowsResult = await supabaseAdmin
181	        .from("production_department_products")
182	        .select("id,sku_code")
183	        .in("sku_code", removedOwnerSkus)
184	        .order("id", { ascending: true });
185	      if (fallbackRowsResult.error) {
186	        return Response.json({ error: "Failed to recover product owner after delete" }, { status: 500 });
187	      }
188	
189	      const fallbackIdBySku = new Map();
190	      (fallbackRowsResult.data ?? []).forEach((row) => {
191	        const skuCode = String(row?.sku_code || "").trim().toUpperCase();
192	        if (!skuCode || fallbackIdBySku.has(skuCode)) return;
193	        fallbackIdBySku.set(skuCode, row.id);
194	      });
195	      const fallbackIds = Array.from(fallbackIdBySku.values());
196	      if (fallbackIds.length) {
197	        const ownerUpdateResult = await supabaseAdmin
198	          .from("production_department_products")
199	          .update({ is_owner: true })
200	          .in("id", fallbackIds);
201	        if (ownerUpdateResult.error) {
202	          return Response.json({ error: "Failed to set fallback product owner" }, { status: 500 });
203	        }
204	      }
205	    }
206	
207	    return Response.json({ ok: true });
208	  } catch (error) {
209	    return jsonError(error);
210	  }
211	}

