10	async function loadSectionCatalog(supabaseAdmin, { includeInactiveSections = false } = {}) {
11	  const [templatesResult, sectionsResult] = await Promise.all([
12	    supabaseAdmin
13	      .from("production_schedule_templates")
14	      .select("id,dept_id,is_active,production_departments(id,code,name)")
15	      .order("created_at", { ascending: false }),
16	    supabaseAdmin
17	      .from("production_schedule_section_defs")
18	      .select("id,template_id,name,display_order,color_theme")
19	      .order("display_order", { ascending: true })
20	      .order("name", { ascending: true }),
21	  ]);
22	
23	  if (templatesResult.error) {
24	    throw new Error("Failed to load schedule templates");
25	  }
26	  if (sectionsResult.error) {
27	    throw new Error("Failed to load schedule sections");
28	  }
29	
30	  const activeTemplateByDepartment = new Map();
31	  (templatesResult.data ?? []).forEach((template) => {
32	    const departmentId = String(template?.dept_id || "").trim();
33	    if (!departmentId || activeTemplateByDepartment.has(departmentId)) return;
34	    if (!includeInactiveSections && template?.is_active !== true) return;
35	    activeTemplateByDepartment.set(departmentId, template);
36	  });
37	
38	  const templatesById = new Map();
39	  activeTemplateByDepartment.forEach((template) => {
40	    templatesById.set(String(template?.id || "").trim(), template);
41	  });
42	
43	  return (sectionsResult.data ?? [])
44	    .map((section) => {
45	      const template = templatesById.get(String(section?.template_id || "").trim());
46	      const department = template?.production_departments || null;
47	      if (!template || !department) return null;
48	      return {
49	        id: section.id,
50	        name: String(section?.name || "").trim() || null,
51	        display_order: Number(section?.display_order ?? 0) || 0,
52	        color_theme: section?.color_theme || null,
53	        template_id: section?.template_id || null,
54	        department_id: department?.id || null,
55	        department_code: String(department?.code || "").trim().toUpperCase() || null,
56	        department_name: String(department?.name || "").trim() || null,
57	      };
58	    })
59	    .filter(Boolean);
60	}
