84	export async function GET(request) {
85	  try {
86	    await requirePermissionKeys(request, [
87	      "production-line-settings-view",
88	      "production-line-settings-manage",
89	      "production-line-planning-view",
90	      "production-line-planning-manage",
91	      "plan.calculate_own_dept",
92	      "plan.edit_own_dept",
93	    ]);
94	
95	    const { searchParams } = new URL(request.url);
96	    const includeInactive = searchParams.get("includeInactive") === "true";
97	    const includeInactiveSections = searchParams.get("includeInactiveSections") === "true";
98	    const sectionDefIdFilter = String(searchParams.get("sectionDefId") || "").trim();
99	    const departmentIdFilter = String(searchParams.get("departmentId") || "").trim();
100	
101	    const supabaseAdmin = getSupabaseAdmin();
102	    const [sections, assignmentRows, masterShiftRows] = await Promise.all([
103	      loadSectionCatalog(supabaseAdmin, { includeInactiveSections }),
104	      loadSectionShiftAssignments(supabaseAdmin, { includeInactive }),
105	      supabaseAdmin
106	        .from("production_shifts")
107	        .select("id,code,name,start_time,end_time,crosses_midnight,sort_order,is_active")
108	        .is("deleted_at", null)
109	        .order("sort_order", { ascending: true })
110	        .order("name", { ascending: true }),
111	    ]);
112	
113	    if (masterShiftRows.error) {
114	      return Response.json({ error: "Failed to load production shifts" }, { status: 500 });
115	    }
116	
117	    const sectionSet = new Set(
118	      sections
119	        .filter((section) => {
120	          if (sectionDefIdFilter && String(section.id || "").trim() !== sectionDefIdFilter) return false;
121	          if (departmentIdFilter && String(section.department_id || "").trim() !== departmentIdFilter) return false;
122	          return true;
123	        })
124	        .map((section) => String(section.id || "").trim())
125	    );
126	
127	    const filteredAssignments = assignmentRows
128	      .filter((row) => {
129	        const key = String(row?.section_def_id || "").trim();
130	        return !sectionSet.size || sectionSet.has(key);
131	      })
132	      .map((row) => mapSectionShiftRow(row));
133	
134	    const filteredSections = sections.filter((section) => sectionSet.has(String(section.id || "").trim()) || (!sectionDefIdFilter && !departmentIdFilter));
135	    const groupedSections = buildSectionShiftGroups(filteredSections, filteredAssignments);
136	
137	    return Response.json({
138	      data: filteredAssignments,
139	      sections: groupedSections,
140	      masterShifts: (masterShiftRows.data ?? []).map(mapShiftRow),
141	    });
142	  } catch (error) {
143	    return jsonError(error);
144	  }
145	}
